Lemma gworld_piece srci tbi smi eni ki ei Y Mi Mx mdx crx LBh My (Pf : Z -> Prop) (Bq nq : Z) :
  gworld srci tbi smi eni ki ei Y Mi Mx mdx crx LBh ->
  mem_grows Mx My -> (forall i, 0 <= i < 2 ^ 64 -> ~ Pf i -> My (Z_to_bv 64 i) = Mx (Z_to_bv 64 i)) ->
  (forall a, Pf a -> (sp - 160 <= a < sp - 56) \/ (fb + 40 + 360 <= a < fb + 40 + 384) \/ (Bq <= a < Bq + nq)) ->
  (forall B' m', In (B', m') (oblk srci tbi eni ki) -> Bq + nq <= B' \/ B' + m' <= Bq) ->
  (forall a, Bq <= a < Bq + nq -> PMK.cwr L LBh a /\ a < sp - 26624 /\ ~ (65536 <= a < 974848) /\ ~ L5C.kept L LBX sp 26624 (PEC.W_crun CAD EE fb) a) ->
  gworld srci tbi smi eni ki ei Y Mi My mdx crx LBh.
