(* [comment removed for export] *)
Lemma grow_rest_C (n : Z) fxi Ri Mi mdi cri moi dni dpi srci tbi tgi vbi vki stki smi eni ki ei Y fx1 R1 M1 :
  mid fxi Ri Mi mdi cri (PM.PST moi dni dpi srci tbi tgi vbi vki stki) smi eni ki ei Y -> s_ec Y = false ->
  Z.of_nat (length stki) = 2 ^ vki -> vki <= 10 -> 0 <= n <= 16777216 ->
  mem_grows Mi M1 ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 160 <= i < sp - 160 + 64) -> ~ (sp - 96 <= i < sp - 96 + 40) -> M1 (Z_to_bv 64 i) = Mi (Z_to_bv 64 i)) ->
  (forall j, In j CSK -> getr R1 (PMK.reg j) = getr Ri (PMK.reg j)) ->
  getr R1 (PMK.reg 1) = Z_to_bv 64 0x39a90 -> getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 160) -> getr R1 (PMK.reg 8) = Z_to_bv 64 (2 ^ (vki + 1)) ->
  getr R1 (PMK.reg 9) = Z_to_bv 64 (2 ^ vki) -> getr R1 (PMK.reg 10) = Z_to_bv 64 (32 * 2 ^ (vki + 1)) -> getr R1 (PMK.reg 18) = Z_to_bv 64 (fb + 432) ->
  getr R1 (PMK.reg 19) = Z_to_bv 64 n -> getr R1 (PMK.reg 20) = Z_to_bv 64 (fb + 40 + 360) ->
  L5.u64_at RSEGS M1 (sp - 160) (sp - 96) -> L5.u64_at RSEGS M1 (sp - 152) 0x398ac -> L5.u64_at RSEGS M1 (sp - 64) (fb + 40 + 360) ->
  L5.u64_at RSEGS M1 (sp - 72) 0 -> L5.u64_at RSEGS M1 (sp - 136) (fb + 8) -> L5.u64_at RSEGS M1 (sp - 128) (fb + 40) ->
  L5.u64_at RSEGS M1 (sp - 120) 0x3bb64 ->
  hi_heap HI (PEC.owned (PM.PST moi dni dpi srci tbi tgi vbi vki stki) eni ki ++ LBX) cri M1 (m_vmmaps mdi) ->
  (forall fx2 R2 M2 md2 B,
      mid fx2 R2 M2 md2 (debit L cri (32 * 2 ^ (vki + 1))) (PM.PST moi dni dpi srci tbi tgi B (vki + 1) (stki ++ [PEC.ps_conv (PS Mkey n 0 0)])) smi eni ki ei
          (w_stk (PS Mkey n 0 0 :: s_stk Y) Y) ->
      getr R2 (PMK.reg 1) = Z_to_bv 64 0x3bc80 -> getr R2 (PMK.reg 10) = Z_to_bv 64 (fb + 432) -> getr R2 (PMK.reg 11) = Z_to_bv 64 n ->
      getr R2 (PMK.reg 12) = Z_to_bv 64 0 -> getr R2 (PMK.reg 13) = Z_to_bv 64 (fb + 40) -> getr R2 (PMK.reg 14) = Z_to_bv 64 (fb + 8) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 0x3644c M2 md2) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0xb2f40 M1 mdi) K.
Proof.
Local Ltac by2 AG H := lazymatch type of AG with (forall a m, _ -> _ -> L5C.agree_on ?Ma ?Mb a m) => apply (L5C.u64_at_agree RSEGS Ma Mb); [apply AG; lia|lia|lia| exact H] end.
Local Ltac ggrow PC SZ fx2 R2 M2 md2 B sp fb vbi n LB1 n0 cri K HH2 Mh2 Ml2 STK2 :=
    pose proof (PC fx2 R2 M2 (fun j => match j with 2%nat => sp | 34%nat => vbi | 36%nat => fb + 40 | 37%nat => fb + 432 | 38%nat => fb + 8 | 48%nat => n | 52%nat => B | _ => 0 end)) as PA3;
    cbn beta iota in PA3;
    PMK.feed PA3 ltac:(first [PMK.sc | progress (unfold PEUBGP6.aligned); first [assumption | (clear; lia)] | (unfold hl_ceil in *; lia) ]);
    destruct PA3 as (fx3 & R3 & M3 & MG3 & _ & FRZ3 & MS3 & KS3 & Z1 & Z2 & Z8 & Z9 & Z11 & Z12 & Z13 & Z14 & Z15 & Z16 & Z18 & C144_3 & C136_3 & C128_3 & C120_3 & C80_3
                     & D24 & D16 & D8 & D0 & C72_3 & C88_3 & C96_3 & C152_3 & C160_3 & C64_3);
    apply (PMK.spiece RSEGS L HI KL HIok LB1 (debit L cri n0) M2 md2 fx2 fx3 R2 0x39a38 R3 0xadfbc M3
             (fun a => (sp - 160 <= a < sp - 160 + 64) \/ (sp - 96 <= a < sp - 96 + 40) \/ (B + SZ + 0 <= a < B + SZ + 0 + 32)) K HH2 Mh2 Ml2 ltac:(lia) MS3 MG3);
    [ intros a Ha N; apply FRZ3; [exact Ha| intros HX; apply N; left; exact HX| intros HX; apply N; right; left; exact HX| intros HX; apply N; right; right; exact HX]
    | intros a [Pa|[Pa|Pa]]; [ apply (PMK.cwr_stack L LB1 M2 sp 26624 a STK2); lia | apply (PMK.cwr_stack L LB1 M2 sp 26624 a STK2); lia
                             | apply (PMK.cwr_block L LB1 B n0); [unfold LB1; left; reflexivity| lia] ]
    | intros a; apply PMK.or_dec; [apply PMK.rng_dec| apply PMK.or_dec; apply PMK.rng_dec]
    | intros HH3 ].
