(* [comment removed for export] *)
Lemma grow_alloc_I fxi Ri Mi mdi cri moi dni dpi srci tbi tgi vbi vki stki smi eni ki ei Y :
  mid fxi Ri Mi mdi cri (PM.PST moi dni dpi srci tbi tgi vbi vki stki) smi eni ki ei Y ->
  Z.of_nat (length stki) = 2 ^ vki -> vki <= 10 ->
  getr Ri (PMK.reg 19) = Z_to_bv 64 (fb + 40 + 24) ->
  (forall fx1 R1 M1, mem_grows Mi M1 ->
      (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 160 <= i < sp - 160 + 64) -> ~ (sp - 96 <= i < sp - 96 + 40) -> M1 (Z_to_bv 64 i) = Mi (Z_to_bv 64 i)) ->
      (forall j, In j CSK -> getr R1 (PMK.reg j) = getr Ri (PMK.reg j)) ->
