Proof.
Local Ltac galloci PC fxi Ri Mi mdi cri K sp fb vbi STK HHi Mh Ml KX X9 X18 :=
    pose proof (PC fxi Ri Mi (fun j => match j with 2%nat => sp | 34%nat => vbi | 36%nat => fb + 40 | 37%nat => fb + 432 | 38%nat => fb + 8 | _ => 0 end)) as PA1;
    cbn beta iota in PA1;
    PMK.feed PA1 ltac:(first [PMK.sc | progress (unfold PEUBGP5.aligned); first [assumption | (clear; lia)] | lia ]);
    destruct PA1 as (fx1 & R1 & M1 & MG1 & _ & FRZ1 & MS1 & KS1 & Y1 & Y2 & Y8 & Y9 & Y10 & Y11 & Y12 & Y13 & Y14 & Y19 & C160 & C152 & C64 & C72 & C136 & C128 & C120);
    apply (PMK.spiece RSEGS L HI KL HIok _ cri Mi mdi fxi fx1 Ri 0x3b954 R1 0xb2ef4 M1 (fun a => (sp - 160 <= a < sp - 160 + 64) \/ (sp - 96 <= a < sp - 96 + 40)) K HHi Mh Ml ltac:(lia) MS1 MG1);
    [ intros a Ha N; apply FRZ1; [exact Ha| intros HX; apply N; left; exact HX| intros HX; apply N; right; exact HX]
    | intros a Pa; apply (PMK.cwr_stack L _ Mi sp 26624 a STK); lia
    | intros a; apply PMK.or_dec; apply PMK.rng_dec
    | intros HH1; apply (KX fx1 R1 M1 MG1);
      [ intros i Hi N1 N2; apply FRZ1; [exact Hi| exact N1| exact N2]
      | intros j Hj; apply KS1; clear - Hj; cbn in Hj; decompose [or] Hj; subst; first [PMK.inl | contradiction]
      | exact Y1 | exact Y2 | PMK.greg | PMK.greg | PMK.greg | rewrite (KS1 18%nat) by PMK.inl; exact X18
      | exact Y19 | exact C160 | exact C152 | exact C64 | exact C72 | exact C136 | exact C128 | exact C120 | exact HH1 ] ].
