(* [comment removed for export] *)
Lemma grow_cpy_I (sz n0 : Z) fxi Ri Mi mdi cri moi dni dpi srci tbi tgi vbi vki stki smi eni ki ei Y fx3 R3 M3 md2 B :
  mid fxi Ri Mi mdi cri (PM.PST moi dni dpi srci tbi tgi vbi vki stki) smi eni ki ei Y ->
  Z.of_nat (length stki) = 2 ^ vki -> vki <= 10 -> sz = 32 * 2 ^ vki -> n0 = 2 * sz ->
  gworld srci tbi smi eni ki ei Y Mi M3 md2 (debit L cri n0) ((B, n0) :: (PEC.owned (PM.PST moi dni dpi srci tbi tgi vbi vki stki) eni ki ++ LBX)) ->
  L5C.fresh_block L (PEC.owned (PM.PST moi dni dpi srci tbi tgi vbi vki stki) eni ki ++ LBX) M3 B n0 ->
  (forall j, In j CSK -> getr R3 (PMK.reg j) = getr R (PMK.reg j)) ->
  (forall i, 0 <= i < sz -> M3 (Z_to_bv 64 (vbi + i)) = Mi (Z_to_bv 64 (vbi + i))) -> L5.defined M3 vbi sz ->
  L5.u64_at RSEGS M3 (fb + 40 + 360) vbi -> L5.u64_at RSEGS M3 (fb + 40 + 368) (vbi + sz) -> L5.u64_at RSEGS M3 (fb + 40 + 376) (vbi + sz) ->
  L5.u32_at RSEGS M3 (B + sz) 9 -> L5.u64_at RSEGS M3 (B + (sz + 8)) 0 -> L5.u8_at RSEGS M3 (B + (sz + 16)) 0 -> L5.u64_at RSEGS M3 (B + (sz + 24)) 0 ->
  L5.u64_at RSEGS M3 (sp - 96) B -> L5.u64_at RSEGS M3 (sp - 88) (B + sz) -> L5.u64_at RSEGS M3 (sp - 80) (B + (sz + 32)) -> L5.u64_at RSEGS M3 (sp - 72) (B + n0) ->
  L5.u64_at RSEGS M3 (sp - 64) (fb + 40 + 360) ->
  L5.u64_at RSEGS M3 (sp - 144) (fb + 432) -> L5.u64_at RSEGS M3 (sp - 136) (fb + 8) -> L5.u64_at RSEGS M3 (sp - 128) (fb + 40) -> L5.u64_at RSEGS M3 (sp - 120) 0x3ba90 ->
  getr R3 (PMK.reg 1) = Z_to_bv 64 0x399ac -> getr R3 (PMK.reg 2) = Z_to_bv 64 (sp - 144) -> getr R3 (PMK.reg 8) = Z_to_bv 64 (sp - 96) ->
  getr R3 (PMK.reg 9) = Z_to_bv 64 (fb + 40 + 360) -> getr R3 (PMK.reg 10) = Z_to_bv 64 B -> getr R3 (PMK.reg 11) = Z_to_bv 64 vbi ->
  getr R3 (PMK.reg 12) = Z_to_bv 64 sz -> getr R3 (PMK.reg 18) = Z_to_bv 64 B -> getr R3 (PMK.reg 19) = Z_to_bv 64 (fb + 40 + 360) ->
  (forall fx2 R2 M2 md2' B',
      mid fx2 R2 M2 md2' (debit L cri (32 * 2 ^ (vki + 1))) (PM.PST moi dni dpi srci tbi tgi B' (vki + 1) (stki ++ [PEC.ps_conv (PS Mikey 0 0 0)])) smi eni ki ei
          (w_stk (PS Mikey 0 0 0 :: s_stk Y) Y) ->
      getr R2 (PMK.reg 1) = Z_to_bv 64 0x3bad4 -> getr R2 (PMK.reg 10) = Z_to_bv 64 (fb + 432) -> getr R2 (PMK.reg 11) = Z_to_bv 64 0 ->
      getr R2 (PMK.reg 12) = Z_to_bv 64 (fb + 40) -> getr R2 (PMK.reg 13) = Z_to_bv 64 (fb + 8) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 0x36374 M2 md2') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 0xae008 M3 md2) K.
