(* [comment removed for export] *)
Lemma push_slot_T (n ty : Z) (Xg : st) pos1 fx4 R4 M4 md4 cr4 si4 sm4 e4 :
  mid fx4 R4 M4 md4 cr4 si4 sm4 en k e4 (w_pos pos1 Xg) -> s_ec X = false -> 0 <= n <= 16777216 ->
  getr R4 (PMK.reg 10) = Z_to_bv 64 n -> getr R4 (PMK.reg 19) = Z_to_bv 64 (fb + 40 + 24) ->
  getr R4 (PMK.reg 20) = Z_to_bv 64 1 -> L5.u8_at RSEGS M4 (sp - 97) ty -> 0 <= ty <= 255 ->
  s_more Xg = true -> s_ec Xg = s_ec X -> s_stk Xg = s_stk X -> s_estk Xg = s_estk X -> s_edepth Xg = s_edepth X -> s_lo Xg = s_lo X -> s_hi Xg = s_hi X -> s_bad Xg = s_bad X ->
  Z.of_nat (length (s_stk X)) <= 1024 ->
  r_begin p true X = w_more true (e_begin_len 0 n (w_stk (PS Mtkey n ty 0 :: s_stk Xg) (w_pos pos1 Xg))) ->
